from pyspark import pipelines as dp
from pyspark.sql.functions import expr

rules = {
  "valid_pickup_zip": "pickup_zip IS NOT NULL",
  "valid_dropoff_zip": "dropoff_zip IS NOT NULL",
}
quarantine_rules = "NOT({0})".format(" AND ".join(rules.values()))

@dp.table(temporary=True, partition_cols=["is_quarantined"])
@dp.expect_all(rules)
def trips_quarantine():
    return (spark.readStream.table("raw_trips")
            .withColumn("is_quarantined", expr(quarantine_rules)))

@dp.temporary_view
def valid_trips():
    return spark.read.table("trips_quarantine").filter("is_quarantined = false")

@dp.temporary_view
def invalid_trips():
    return spark.read.table("trips_quarantine").filter("is_quarantined = true")
